def minDifference(nums):
    n = len(nums)
    max_adj = 0          # fixed differences between two known neighbours
    mn, mx = float('inf'), 0
    runs = []            # (left neighbour, right neighbour, run has length >= 2)
    i = 0
    while i < n:
        if nums[i] != -1:
            if i + 1 < n and nums[i + 1] != -1:
                max_adj = max(max_adj, abs(nums[i] - nums[i + 1]))
            i += 1
            continue
        j = i
        while j < n and nums[j] == -1:
            j += 1
        l = nums[i - 1] if i > 0 else None
        r = nums[j] if j < n else None
        if l is None and r is None:
            return 0     # every element is -1
        if l is None:
            l = r
        if r is None:
            r = l
        mn = min(mn, l, r)
        mx = max(mx, l, r)
        runs.append((l, r, j - i >= 2))
        i = j

    if not runs:
        return max_adj

    def check(d):
        x, y = mn + d, mx - d
        for l, r, long_run in runs:
            best = min(max(abs(l - x), abs(r - x)), max(abs(l - y), abs(r - y)))
            if long_run:
                gap = abs(x - y)
                best = min(best,
                           max(abs(l - x), gap, abs(r - y)),
                           max(abs(l - y), gap, abs(r - x)))
            if best > d:
                return False
        return True

    lo, hi = max_adj, max(max_adj, (mx - mn + 1) // 2)
    while lo < hi:
        mid = (lo + hi) // 2
        if check(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo
